frappe.provide('frappe.views');

$(document).on('page-change', function() {
    let route = frappe.get_route();
    if (route[0] === 'dashboard-view' && route[1] === 'Sales Analysis') {
        // Wait for the dashboard to fully render (charts need time to load)
        setTimeout(function() {
            add_set_filters_button();
        }, 1500);
    }
});

function add_set_filters_button() {
    // Check if button already exists
    if ($('#sales-analysis-set-filters-btn').length > 0) {
        return;
    }

    // Find the page actions area in the standard_actions toolbar
    let $page_head = $('.page-head');
    if (!$page_head.length) return;

    // Create the "Set Filters" button and inject it into the page header
    let $btn = $(`<button id="sales-analysis-set-filters-btn" 
        class="btn btn-primary btn-sm" 
        style="margin-left: 10px; margin-right: 10px;">
        ${__('Set Filters')}
    </button>`);

    // Insert the button into the standard actions area (right side of header)
    let $actions = $page_head.find('.standard-actions');
    if ($actions.length) {
        $actions.prepend($btn);
    } else {
        $page_head.find('.page-head-content').append($btn);
    }

    $btn.on('click', function() {
        show_filter_dialog();
    });
}

function show_filter_dialog() {
    if (!window.sales_analysis_filter_dialog) {
        window.sales_analysis_filter_dialog = new frappe.ui.Dialog({
            title: __('Set Default Filters'),
            fields: [
                {
                    label: 'From Date',
                    fieldname: 'master_from_date',
                    fieldtype: 'Date',
                    reqd: 1,
                    default: frappe.datetime.add_months(frappe.datetime.get_today(), -1)
                },
                {
                    label: 'To Date',
                    fieldname: 'master_to_date',
                    fieldtype: 'Date',
                    reqd: 1,
                    default: frappe.datetime.get_today()
                },
                {
                    label: 'Limit',
                    fieldname: 'master_limit',
                    fieldtype: 'Int',
                    reqd: 1,
                    default: 5
                }
            ],
            primary_action_label: __('Set'),
            primary_action: (values) => {
                update_dashboard_charts(values);
                window.sales_analysis_filter_dialog.hide();
            }
        });
    }
    window.sales_analysis_filter_dialog.show();
}

function update_dashboard_charts(values) {
    let from_date = values.master_from_date;
    let to_date = values.master_to_date;
    let limit = values.master_limit;

    if (!from_date || !to_date) {
        frappe.msgprint(__('Please select both From Date and To Date'));
        return;
    }

    // In Frappe v15/v16, cur_list might not be set for dashboard-view routes.
    // So we search for the active DashboardView instance in frappe.views.list_view
    let dashboard_view = null;
    if (window.cur_list && window.cur_list.chart_group) {
        dashboard_view = window.cur_list;
    } else if (frappe.views && frappe.views.list_view) {
        for (let key in frappe.views.list_view) {
            let view = frappe.views.list_view[key];
            if (view && view.chart_group && view.chart_group.widgets) {
                dashboard_view = view;
                break; // Found the active dashboard view
            }
        }
    }

    if (!dashboard_view || !dashboard_view.chart_group || !dashboard_view.chart_group.widgets) {
        frappe.msgprint(__('Dashboard charts not loaded yet. Please wait and try again.'));
        return;
    }

    // All charts on Sales Analysis are Report-type charts.
    // For Report charts, widget.filters holds the report filters (from_date, to_date, limit).
    // widget.fetch_and_update_chart() re-fetches data using those filters and re-renders.
    dashboard_view.chart_group.widgets.forEach(widget => {
        if (!widget.filters) {
            widget.filters = {};
        }
        // Update the filters on the widget
        widget.filters.from_date = from_date;
        widget.filters.to_date = to_date;
        if (limit) {
            widget.filters.limit = limit;
        }
        
        // Re-fetch and re-render the chart with the new filters
        if (typeof widget.fetch_and_update_chart === 'function') {
            widget.fetch_and_update_chart();
        }
    });

    frappe.show_alert({
        message: __('Filters applied: {0} to {1}, Limit: {2}', [from_date, to_date, limit]),
        indicator: 'green'
    });
}
